create.endpoint:
POST /api/alerts
الجسم: { patient_id, appointment_id, message, alert_date, alert_time, repeat_count, repeat_interval }
الاستجابة: { success: true, alert_id, message }

update.endpoint:
PUT /api/alerts/{id}
الجسم: { message, alert_date, alert_time, repeat_count, repeat_interval, is_active, is_dismissed }
الاستجابة: { success: true, message }

create.endpoint:
POST /api/notes
الجسم: { title, content, x, y, width, height, color }
الاستجابة: { success: true, note: {...} }

update.endpoint:
PUT /api/notes/{id}
الجسم: { title?, content?, x?, y?, width?, height?, color? }
الاستجابة: { success: true, note: {...} }

change_password.endpoint:
POST /doctor/profile/change-password
الجسم: { new_password, confirm_password }
الاستجابة: يعيد التوجيه إلى /doctor/profile?success=... أو ?error=...

update_field.endpoint:
POST /doctor/profile/update-field
الجسم: { field, value }
الاستجابة: { success: true/false, message }

upload_file.endpoint:
POST /api/patients/files/upload
Body: FormData مع patient_id, file, file_type, description
Response: { success: true, file_id, message }

capture_image.endpoint:
POST /api/patients/files/capture
Body: FormData مع patient_id, image (base64 أو blob), description
Response: { success: true, file_id, message }
